function loadAssets() {
  return Promise.all(assetPaths.map((path) => new Promise((resolve) => {
    const img = new Image();
    img.onload = () => {
      assets[path] = img;
      resolve();
    };
    img.onerror = () => {
      resolve();
    };
    img.src = path;
  }))).then(() => {
    assetsReady = true;
  });
}

function resize() {
  const dpr = window.devicePixelRatio || 1;
  const viewport = viewportSize();
  const width = Math.min(viewport.width, 430);
  const height = viewport.height;
  scale = width / BASE_W;
  BASE_H = Math.max(1900, Math.round(height / scale));
  const safePx = parseFloat(getComputedStyle(document.documentElement).getPropertyValue("--safe-bottom")) || 0;
  const mobileSafePx = width <= 430 ? 24 : 0;
  SAFE_BOTTOM = Math.round(Math.max(safePx, mobileSafePx) / scale);
  NAV_TOP = BASE_H - 222;
  canvas.width = Math.round(width * dpr);
  canvas.height = Math.round(height * dpr);
  canvas.style.width = `${width}px`;
  canvas.style.height = `${height}px`;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  state.scrollY = clamp(state.scrollY, 0, maxScrollForView(state.view));
  ox = 0;
  oy = 0;
  if (assetsReady) draw();
  else {
    ctx.fillStyle = BG;
    ctx.fillRect(0, 0, width, height);
  }
}

function maxScrollForView(view = state.view) {
  if (view === "home") return 1580;
  if (view === "popular") return 540;
  if (view === "perps") return 560;
  return 0;
}

function viewportSize() {
  const vv = window.visualViewport;
  const doc = document.documentElement;
  const width = Math.min(
    window.innerWidth || BASE_W,
    doc?.clientWidth || window.innerWidth || BASE_W,
    vv?.width || window.innerWidth || BASE_W,
  );
  const height = Math.min(
    window.innerHeight || WEB_VIEW_H,
    doc?.clientHeight || window.innerHeight || WEB_VIEW_H,
    vv?.height || window.innerHeight || WEB_VIEW_H,
  );
  return {
    width,
    height,
  };
}

function toBase(evt) {
  const t = evt.touches ? evt.touches[0] : evt;
  const rect = canvas.getBoundingClientRect();
  return {
    x: (t.clientX - rect.left - ox) / scale,
    y: (t.clientY - rect.top - oy) / scale,
  };
}

function font(size, weight = 400, display = false) {
  return `${weight} ${size}px "${display ? "SF Pro Display Local" : "SF Pro Text Local"}", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif`;
}

function text(value, x, y, size, color = TEXT, align = "left", weight = 400, display = false) {
  ctx.fillStyle = color;
  ctx.font = font(size, weight, display);
  ctx.textAlign = align;
  ctx.textBaseline = "alphabetic";
  ctx.fillText(value, x, y);
}

function rect(x, y, w, h, color, r = 0) {
  ctx.fillStyle = color;
  if (r <= 0) {
    ctx.fillRect(x, y, w, h);
    return;
  }
  ctx.beginPath();
  if (ctx.roundRect) ctx.roundRect(x, y, w, h, r);
  else pathRoundRect(x, y, w, h, r);
  ctx.fill();
}

function circle(cx, cy, r, color) {
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.arc(cx, cy, r, 0, Math.PI * 2);
  ctx.fill();
}

function strokeRect(x, y, w, h, color, r = 0, lw = 2, dash = null) {
  ctx.strokeStyle = color;
  ctx.lineWidth = lw;
  ctx.setLineDash(dash || []);
  ctx.beginPath();
  if (r <= 0) ctx.rect(x, y, w, h);
  else if (ctx.roundRect) ctx.roundRect(x, y, w, h, r);
  else pathRoundRect(x, y, w, h, r);
  ctx.stroke();
  ctx.setLineDash([]);
}

function pathRoundRect(x, y, w, h, r) {
  const rr = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + rr, y);
  ctx.lineTo(x + w - rr, y);
  ctx.quadraticCurveTo(x + w, y, x + w, y + rr);
  ctx.lineTo(x + w, y + h - rr);
  ctx.quadraticCurveTo(x + w, y + h, x + w - rr, y + h);
  ctx.lineTo(x + rr, y + h);
  ctx.quadraticCurveTo(x, y + h, x, y + h - rr);
  ctx.lineTo(x, y + rr);
  ctx.quadraticCurveTo(x, y, x + rr, y);
  ctx.closePath();
}

function img(path, x, y, w, h, alpha = 1) {
  const image = assets[path];
  if (!image) return;
  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.drawImage(image, x, y, w, h);
  ctx.restore();
}

function circleImg(path, x, y, size) {
  const image = assets[path];
  ctx.save();
  ctx.beginPath();
  ctx.arc(x + size / 2, y + size / 2, size / 2, 0, Math.PI * 2);
  ctx.clip();
  if (image) ctx.drawImage(image, x, y, size, size);
  else rect(x, y, size, size, "#333", size / 2);
  ctx.restore();
}

function line(x1, y1, x2, y2, color = TEXT, width = 6) {
  ctx.strokeStyle = color;
  ctx.lineWidth = width;
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x2, y2);
  ctx.stroke();
}

function money(v) {
  return v.toLocaleString("ru-RU", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

function amount(v, max = 6) {
  return v.toLocaleString("ru-RU", { maximumFractionDigits: max }).replace(/\u00a0/g, " ");
}

function fiat(v) {
  return `${money(v)} $`;
}

function usd(v) {
  return `$${money(v)}`;
}

function marketPrice(symbol) {
  const extraPrices = {
    LINK: 9.53,
    CAKE: 1.41,
    ASTER: 0.6803,
    XAUt: 4377.91,
    PAXG: 4544.82,
    TRUMP: 0,
  };
  const value = symbol === "TRX" ? state.balances.trxPrice : marketAssets[symbol]?.priceUsd ?? extraPrices[symbol];
  return value ? usd(value) : "$--";
}

function coinPriceUsd(symbol, network = "") {
  if (symbol === "TRX") return state.balances.trxPrice;
  if (symbol === "TON") return marketAssets.TON.priceUsd;
  if (symbol === "USDT" && network === "TON") return state.balances.tonUsdtPrice;
  if (symbol === "USDT") return state.balances.usdtPrice;
  const asset = marketAssets[symbol];
  if (asset?.priceUsd) return asset.priceUsd;
  return 0;
}

function walletAssets() {
  return [
    {
      id: "usdtTron",
      symbol: "USDT",
      network: "Tron",
      balance: state.balances.usdtTron,
      price: coinPriceUsd("USDT", "Tron"),
      coin: "assets/coins/usdt.png",
      badge: "assets/coins/195.webp",
    },
    {
      id: "trx",
      symbol: "TRX",
      network: "Tron",
      balance: state.balances.trx,
      price: coinPriceUsd("TRX", "Tron"),
      coin: "assets/coins/195.webp",
    },
    {
      id: "usdtTon",
      symbol: "USDT",
      network: "TON",
      balance: state.balances.usdtTon,
      price: coinPriceUsd("USDT", "TON"),
      coin: "assets/coins/usdt.png",
      badge: "ton",
    },
  ].map((asset) => ({
    ...asset,
    fiat: asset.balance * asset.price,
  }));
}

function walletTotalUsd() {
  return walletAssets().reduce((sum, asset) => sum + asset.fiat, 0);
}

function ensureWalletEditorDraft() {
  if (!state.walletEditorDraft) {
    state.walletEditorDraft = {
      usdtTron: state.balances.usdtTron,
      trx: state.balances.trx,
      usdtTon: state.balances.usdtTon,
    };
  }
  return state.walletEditorDraft;
}

function walletEditorAssets() {
  const draft = ensureWalletEditorDraft();
  return [
    {
      id: "usdtTron",
      symbol: "USDT",
      network: "Tron",
      balance: draft.usdtTron,
      price: coinPriceUsd("USDT", "Tron"),
      coin: "assets/coins/usdt.png",
      badge: "assets/coins/195.webp",
    },
    {
      id: "trx",
      symbol: "TRX",
      network: "Tron",
      balance: draft.trx,
      price: coinPriceUsd("TRX", "Tron"),
      coin: "assets/coins/195.webp",
    },
    {
      id: "usdtTon",
      symbol: "USDT",
      network: "TON",
      balance: draft.usdtTon,
      price: coinPriceUsd("USDT", "TON"),
      coin: "assets/coins/usdt.png",
      badge: "ton",
    },
  ].map((asset) => ({
    ...asset,
    fiat: asset.balance * asset.price,
  }));
}

function walletEditorTotalUsd() {
  return walletEditorAssets().reduce((sum, asset) => sum + asset.fiat, 0);
}

function openWalletEditor() {
  state.walletEditorDraft = null;
  ensureWalletEditorDraft();
  state.sheet = "walletEditor";
}

function applyWalletEditor() {
  const draft = ensureWalletEditorDraft();
  state.balances.usdtTron = draft.usdtTron;
  state.balances.trx = draft.trx;
  state.balances.usdtTon = draft.usdtTon;
  state.walletEditorDraft = null;
  state.sheet = null;
}

function ellipsizeMiddle(value, max) {
  if (!value) return "";
  if (value.length <= max) return value;
  const left = Math.max(4, Math.floor((max - 3) / 2));
  const right = Math.max(4, max - 3 - left);
  return `${value.slice(0, left)}...${value.slice(-right)}`;
}

function ellipsizeAddress(value) {
  return ellipsizeMiddle(value, 13);
}

function feeSymbol(network = state.sendNetwork) {
  if (network === "Ethereum") return "ETH";
  if (network === "Tron") return "TRX";
  if (network === "TON") return "TON";
  return "BNB";
}

function feeAmount(network = state.sendNetwork, value = state.sendAmount) {
  const safe = Math.max(0.000001, value);
  if (network === "Ethereum") return 0.0012 + safe * 0.00001;
  if (network === "Tron") return 1.1 + safe * 0.001;
  if (network === "TON") return 0.045 + safe * 0.0004;
  return 0.00021 + safe * 0.000002;
}

function feeFiat(network = state.sendNetwork, value = state.sendAmount) {
  const f = feeAmount(network, value);
  if (network === "Ethereum") return f * coinPriceUsd("ETH");
  if (network === "Tron") return f * state.balances.trxPrice;
  if (network === "TON") return f * coinPriceUsd("TON");
  return f * coinPriceUsd("BNB");
}

function sendAssetDisplay() {
  return state.sendAsset === "USDT_TON" ? "USDT" : state.sendAsset;
}

function sendAssetPrice() {
  if (state.sendAsset === "TRX") return state.balances.trxPrice;
  if (state.sendAsset === "USDT_TON") return state.balances.tonUsdtPrice;
  return state.balances.usdtPrice;
}

function sendBalance() {
  if (state.sendAsset === "TRX") return state.balances.trx;
  if (state.sendAsset === "USDT_TON") return state.balances.usdtTon;
  return state.balances.usdtTron;
}

function setSendAsset(symbol) {
  state.sendAsset = symbol;
  state.sendNetwork = symbol === "TRX" ? "Tron" : symbol === "USDT_TON" ? "TON" : "BNB Smart Chain";
  state.sendAmount = Math.min(Math.max(0.0001, state.sendAmount), Math.max(0.0001, sendBalance()));
}

function setReceiveAsset(symbol, network, address) {
  state.receiveAsset = symbol;
  state.receiveNetwork = network;
  state.receiveAddress = address;
}

// ----- src/20_shell.js -----
function draw() {
  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.restore();

  ctx.save();
  ctx.translate(ox, oy);
  ctx.scale(scale, scale);
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = "source-over";
  ctx.fillStyle = BG;
  ctx.fillRect(0, 0, BASE_W, BASE_H);
  if (state.view === "splash") drawSplash();
  else if (state.view === "onboarding") drawOnboarding();
  else if (state.view === "login") drawLogin();
  else {
    drawStatus();
    if (state.view === "popular") drawPopular();
    else if (state.view === "rewards") drawRewards();
    else if (state.view === "more") drawMore();
    else if (state.view === "marketDetail") drawMarketDetail();
    else if (state.view === "history") drawHistory();
    else if (state.view === "manage") drawManagePage();
    else if (state.view === "swap") drawSwapPage();
    else if (state.view === "perps") drawPerpsPage();
    else if (state.view === "predictions") drawPredictionsPage();
    else {
      ctx.save();
      ctx.translate(0, -state.scrollY);
      drawHomeContent();
      ctx.restore();
      drawScrollIndicator();
      drawHomeTopBar();
      drawHomeBottomNav();
    }
  }
  if (state.sheet) {
    dim();
    drawSheet();
  }
  ctx.restore();

}

function paintHomeDirect() {
  if (state.view !== "home" || state.sheet) return;
  ctx.save();
  ctx.translate(ox, oy);
  ctx.scale(scale, scale);
  ctx.save();
  ctx.translate(0, -state.scrollY);
  drawHomeContent();
  ctx.restore();
  drawScrollIndicator();
  drawHomeTopBar();
  drawHomeBottomNav();
  ctx.restore();
}

function drawStatus() {
}

