function drawSettingsIcon(x, y, type) {
  const color = type === "security" ? "#2d5cf6" :
    type === "bell" ? "#7a4dff" :
    type === "sliders" ? "#2f9e73" :
    type === "link" ? "#2a78ff" :
    type === "book" ? "#b77a2b" :
    type === "support" ? "#24a8db" :
    type === "face" ? "#7a4dff" :
    type === "timer" ? "#2f9e73" :
    type === "scanner" ? "#1f8f5f" :
    type === "key" ? "#d79b25" :
    type === "info" ? "#6b6d75" : "#1c4b2e";
  rect(x, y, 72, 72, color, 22);
  ctx.save();
  ctx.strokeStyle = "#ffffff";
  ctx.fillStyle = "#ffffff";
  ctx.lineWidth = 5;
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  if (type === "wallet") {
    strokeRect(x + 17, y + 20, 38, 32, "#ffffff", 8, 4);
    circle(x + 48, y + 36, 4, "#ffffff");
  } else if (type === "security") {
    strokeRect(x + 22, y + 32, 28, 22, "#ffffff", 7, 4);
    ctx.beginPath();
    ctx.arc(x + 36, y + 32, 12, Math.PI, 0);
    ctx.stroke();
  } else if (type === "bell") {
    ctx.beginPath();
    ctx.arc(x + 36, y + 34, 18, Math.PI * 1.08, Math.PI * 1.92);
    ctx.lineTo(x + 56, y + 50);
    ctx.lineTo(x + 16, y + 50);
    ctx.closePath();
    ctx.stroke();
    circle(x + 36, y + 57, 4, "#ffffff");
  } else if (type === "sliders") {
    line(x + 18, y + 24, x + 54, y + 24, "#ffffff", 4);
    circle(x + 30, y + 24, 6, color);
    strokeRect(x + 24, y + 18, 12, 12, "#ffffff", 3, 4);
    line(x + 18, y + 48, x + 54, y + 48, "#ffffff", 4);
    circle(x + 46, y + 48, 6, color);
    strokeRect(x + 40, y + 42, 12, 12, "#ffffff", 3, 4);
  } else if (type === "link") {
    ctx.beginPath();
    ctx.arc(x + 28, y + 36, 14, Math.PI * 0.35, Math.PI * 1.65);
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(x + 44, y + 36, 14, -Math.PI * 0.65, Math.PI * 0.65);
    ctx.stroke();
  } else if (type === "book") {
    strokeRect(x + 21, y + 16, 30, 44, "#ffffff", 6, 4);
    line(x + 30, y + 26, x + 43, y + 26, "#ffffff", 3);
    line(x + 30, y + 38, x + 43, y + 38, "#ffffff", 3);
  } else if (type === "support") {
    ctx.beginPath();
    ctx.arc(x + 36, y + 36, 22, 0, Math.PI * 2);
    ctx.stroke();
    text("?", x + 36, y + 48, 34, "#ffffff", "center", 700);
  } else if (type === "face") {
    ctx.beginPath();
    ctx.arc(x + 36, y + 36, 22, 0, Math.PI * 2);
    ctx.stroke();
    circle(x + 28, y + 32, 3, "#ffffff");
    circle(x + 44, y + 32, 3, "#ffffff");
    line(x + 28, y + 47, x + 44, y + 47, "#ffffff", 4);
  } else if (type === "timer") {
    ctx.beginPath();
    ctx.arc(x + 36, y + 38, 20, 0, Math.PI * 2);
    ctx.stroke();
    line(x + 36, y + 38, x + 36, y + 25, "#ffffff", 4);
    line(x + 36, y + 38, x + 48, y + 38, "#ffffff", 4);
  } else if (type === "scanner") {
    ctx.beginPath();
    ctx.moveTo(x + 36, y + 14);
    ctx.lineTo(x + 56, y + 24);
    ctx.lineTo(x + 52, y + 48);
    ctx.lineTo(x + 36, y + 60);
    ctx.lineTo(x + 20, y + 48);
    ctx.lineTo(x + 16, y + 24);
    ctx.closePath();
    ctx.stroke();
    line(x + 26, y + 37, x + 34, y + 45, "#ffffff", 4);
    line(x + 34, y + 45, x + 48, y + 29, "#ffffff", 4);
  } else if (type === "key") {
    ctx.beginPath();
    ctx.arc(x + 28, y + 34, 11, 0, Math.PI * 2);
    ctx.stroke();
    line(x + 38, y + 42, x + 56, y + 60, "#ffffff", 5);
    line(x + 49, y + 53, x + 57, y + 45, "#ffffff", 4);
  } else {
    circle(x + 36, y + 23, 4, "#ffffff");
    line(x + 36, y + 36, x + 36, y + 54, "#ffffff", 5);
  }
  ctx.restore();
}

