function walletEditorAssetRow(y, asset, compact = false) {
  const selected = state.walletEditorAsset === asset.id;
  const top = y - (compact ? 78 : 94);
  const height = compact ? 158 : 178;
  const icon = compact ? 76 : 86;
  rect(44, top, 992, height, selected ? "#26352e" : "#242529", 32);
  circleImg(asset.coin, 88, y - (compact ? 54 : 62), icon);
  if (asset.badge === "ton") drawTonBadge(153, y - (compact ? 12 : 17), compact ? 38 : 42);
  else if (asset.badge) circleImg(asset.badge, 153, y - (compact ? 12 : 17), compact ? 38 : 42);
  text(asset.symbol, 190, y - 30, 40, TEXT, "left", 700);
  text(`${asset.network} · ${fiat(asset.price)}`, 190, y + 16, 30, MUTED, "left", 500);
  text(amount(asset.balance, 6), 992, y - 32, 38, TEXT, "right", 700);
  text(fiat(asset.fiat), 992, y + 16, 30, MUTED, "right", 500);
  const buttonY = y + (compact ? 38 : 46);
  walletEditorButton(190, buttonY, 156, 60, "+10", "#34363b");
  walletEditorButton(370, buttonY, 170, 60, "+100", "#34363b");
  walletEditorButton(820, buttonY, 172, 60, "Ввести", GREEN, "#101814");
}

