function drawWalletEditorTxList(layout) {
  const top = layout.txCardY + 82;
  const h = layout.txListH - 100;
  const maxScroll = walletEditorTxMaxScroll(layout);
  state.walletEditorTxScrollY = clamp(state.walletEditorTxScrollY || 0, 0, maxScroll);
  ctx.save();
  ctx.beginPath();
  ctx.rect(44, top, 992, h);
  ctx.clip();
  const sy = state.walletEditorTxScrollY || 0;
  state.txs.forEach((tx, index) => {
    const y = top + 58 + index * layout.txRowStep - sy;
    if (y < top - 80 || y > top + h + 80) return;
    const selected = index === walletEditorSelectedIndex();
    if (selected) rect(62, y - 58, 956, 112, "#303238", 28);
    historyRow(y, tx.sent, tx.title, tx.address, tx.amount, tx.fiat);
    if (tx.date) text(tx.date, 160, y + 54, 24, MUTED, "left", 500);
  });
  ctx.restore();
  if (maxScroll > 0) {
    const thumbH = Math.max(40, h * h / (h + maxScroll));
    const thumbY = top + (h - thumbH) * ((state.walletEditorTxScrollY || 0) / maxScroll);
    rect(1018, thumbY, 8, thumbH, "#5b5c61", 4);
  }
}

