function drawBottomNav(active, dimmed = false) {
  const y = bottomNavY();
  const centers = bottomNavCenters();
  ctx.save();
  drawBottomNavBackdrop(y - 20);
  if (dimmed) ctx.globalAlpha = 0.45;
  ctx.fillStyle = "rgba(24,25,27,0.92)";
  pathRoundRect(8, y, 1064, 182, 92);
  ctx.fill();
  strokeRect(8, y, 1064, 182, "#3a3b3e", 92, 3);
  navItem(centers.home, "home", "\u0413\u043b\u0430\u0432\u043d\u0430\u044f", active === "home");
  navItem(centers.popular, "popular", "\u0420\u044b\u043d\u043a\u0438", active === "popular");
  navItem(centers.perps, "perps", "\u0411\u0435\u0441\u0441\u0440.", active === "perps");
  navItem(centers.more, "more", "\u041f\u043e\u0434\u0440\u043e\u0431\u043d\u0435\u0435", active === "more");
  drawTradeNavItem(centers.trade, active === "trade");
  ctx.restore();
}

